B.aoz=s(["Prime qualit\xe9 du mois (notes des passagers)","\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u062c\u0648\u062f\u0629 \u0627\u0644\u0634\u0647\u0631\u064a\u0629 (\u062a\u0642\u064a\u064a\u0645\u0627\u062a \u0627\u0644\u0631\u0643\u0627\u0628)","\u0627\u0644\u0628\u0631\u064a\u0645 \u062f\u064a\u0627\u0644 \u0627\u0644\u062c\u0648\u062f\u0629 \u062f\u064a\u0627\u0644 \u0627\u0644\u0634\u0647\u0631 (\u0627\u0644\u0646\u0648\u0637 \u062f\u064a\u0627\u0644 \u0627\u0644\u0643\u0644\u064a\u0627\u0646)","Monthly quality bonus (passenger ratings)"],t.s)
B.ah6=s(["Prime qualit\xe9 du mois","\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u062c\u0648\u062f\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u0634\u0647\u0631","\u0627\u0644\u0628\u0631\u064a\u0645 \u062f\u064a\u0627\u0644 \u0627\u0644\u062c\u0648\u062f\u0629 \u062f\u064a\u0627\u0644 \u0627\u0644\u0634\u0647\u0631","Monthly quality bonus"],t.s)
